function longestEvenSpacing(nums: number[]): number {
  const n = nums.length;
  let best = 2;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const d = nums[j] - nums[i];
      let len = 2, want = nums[j] + d;
      for (let k = j + 1; k < n; k++) {
        if (nums[k] === want) { len++; want += d; }
      }
      best = Math.max(best, len);
    }
  }
  return best;
}

