class Solution:
    def longestEvenSpacing(self, nums: List[int]) -> int:
        n, best = len(nums), 2
        for i in range(n):
            for j in range(i + 1, n):
                d = nums[j] - nums[i]
                length, want = 2, nums[j] + d
                for k in range(j + 1, n):
                    if nums[k] == want:
                        length += 1
                        want += d
                best = max(best, length)
        return best

