function longestEvenSpacing(nums: number[]): number {
  const n = nums.length, OFF = 500, W = 1001;
  const len = new Int16Array(n * W); // 0 means "no chain yet"
  let best = 2;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      const d = nums[i] - nums[j] + OFF;
      const prev = len[j * W + d] || 1;
      const cur = prev + 1;
      if (cur > len[i * W + d]) len[i * W + d] = cur;
      if (cur > best) best = cur;
    }
  }
  return best;
}

