class Solution:
    def longestEvenSpacing(self, nums: List[int]) -> int:
        n = len(nums)
        ends = [dict() for _ in range(n)]  # ends[i][d] = longest chain ending at i with step d
        best = 2
        for i in range(n):
            here = ends[i]
            for j in range(i):
                d = nums[i] - nums[j]
                cur = ends[j].get(d, 1) + 1
                if cur > here.get(d, 0):
                    here[d] = cur
                    if cur > best:
                        best = cur
        return best

